mapper.select:
SELECT permission_level
FROM document_permissions
WHERE document_id = #{documentId}
  AND user_id = #{userId}
  AND is_deleted = 0
LIMIT 1

mapper.update:
UPDATE document_permissions
SET is_deleted = 1,
    updated_at = CURRENT_TIMESTAMP
WHERE document_id = #{documentId}
  AND user_id = #{userId}
  AND is_deleted = 0
